232: /** Style déclaré par un dossier de destination, vu depuis une racine Source
233:  *  Data : **premier segment** du chemin relatif. Miroir client de
234:  *  `_style_of_dest_dir` (app.py) — même grammaire `parseFolderName`, tenue
235:  *  honnête par une table de noms testée des deux côtés. null si la destination
236:  *  n'est pas sous une racine connue, ou si le segment ne déclare rien
237:  *  (`_trash`, `2008_08`, dossier capitalisé). */
238: export function styleOfDestDir(destDir: string): string | null {
239:   const root = sourceRoots().find(dir => destDir === dir || destDir.startsWith(dir.endsWith('/') ? dir : `${dir}/`));
240:   if (!root) return null;
241:   const rel = destDir === root ? '' : destDir.substring(root.length).replace(/^\/+/, '');
242:   const seg = rel.split('/')[0];
243:   return seg ? (parseFolderName(seg)?.style ?? null) : null;
244: }
