292: /** Copie `files` (épars) vers `destDir`, patch l'index + le DOM, recharge le
293:  *  journal, vide la sélection et révèle le dossier destination. Renvoie les
294:  *  fullpaths épars effectivement copiés et la note de style éventuelle
295:  *  (EPIC-043). Extrait du handler batch de F5 (EPIC-035) pour être enchaîné par
296:  *  dossier cible depuis l'aperçu de rangement — corps iso-comportement, aucune
297:  *  confirmation ici (l'appelant l'a déjà obtenue). */
298: export async function copyFilesTo(
299:   destDir: string,
300:   files: Array<{ filename: string; eparDir: string; fullpath: string }>,
301: ): Promise<{ copied: string[]; styleNote: string }> {
302:   const copied: string[] = [];
303:   const notes = new Set<string>();
304:   for (const f of files) {
305:     const relPath = state.eparsFiles[f.eparDir]?.[f.filename]?.path;
306:     if (!relPath) continue;
307:     const fullSrc = `${f.eparDir}/${relPath}`;
308:     try {
309:       const res = await api<CopyResponse>('/copy', {
310:         method: 'POST',
311:         body: JSON.stringify({ source_path: fullSrc, dest_dir: destDir, filename: f.filename }),
312:       });
313:       if (!res.ok) continue;
314:       copied.push(f.fullpath);
315:       let relPathNew = f.filename;
316:       const sourceDir = Object.keys(state.sourceFiles).find(dir => destDir === dir || destDir.startsWith(`${dir}/`));
317:       if (sourceDir && destDir.startsWith(sourceDir)) {
318:         const rel = destDir.substring(sourceDir.length).replace(/^\/+/, '');
319:         relPathNew = rel ? `${rel}/${f.filename}` : f.filename;
320:         if (!state.sourceFiles[sourceDir]) state.sourceFiles[sourceDir] = {};
321:         state.sourceFiles[sourceDir][f.filename] = {
322:           path: relPathNew,
323:           year: res.year ?? null,
324:           duration: res.duration ?? null,
325:           codec: res.codec ?? null,
326:           genre: res.genre ?? null,
327:         };
328:       }
329:       patchEparsFileAfterCopy(f.filename, f.eparDir);
330:       patchSourceFileAfterCopy(destDir, f.filename, {
331:         path: relPathNew,
332:         year: res.year ?? null,
333:         duration: res.duration ?? null,
334:         codec: res.codec ?? null,
335:         genre: res.genre ?? null,
336:       });
337:       applyCopyStyle(fullSrc, f.eparDir, f.filename, res);
338:       const note = styleNoteOf(res);
339:       if (note) notes.add(note);
340:     } catch (_) {
341:       /* continue */
342:     }
343:   }
344:   // Trigger EventEmitter for nested sourceFiles mutations
345:   state.sourceFiles = { ...state.sourceFiles };
346:   state.journal = await api('/journal');
347:   state.selectedEparsFiles = new Map();
348:   // EPIC-051 : l'expansion automatique du dossier destination est RETIRÉE —
349:   // le dossier reste plié (le dépliage est un geste explicite : clic ou Enter).
350:   requestAnimationFrame(() => requestAnimationFrame(revalidateFocus));
351:   return { copied, styleNote: [...notes].join('') };
352: }
