354: /** Le dossier destination existe-t-il déjà ? Index scanné (dossiers implicites
355:  *  dans les `path` relatifs) + dossiers ➕ (extra_dirs). Slashes PLIÉS pour la
356:  *  comparaison (forme réelle `…/style//dossier` quand la config porte un slash
357:  *  final — EPIC-050 : on plie au moment de comparer, jamais dans les données).
358:  *  false → /copy créera le dossier (os.makedirs) : la modale porte le badge ➕. */
359: function destExists(destDir: string): boolean {
360:   const dest = destDir.replace(/\/+/g, '/').replace(/\/+$/, '');
361:   for (const extra of state.sourceExtraDirs) {
362:     if (extra.replace(/\/+/g, '/').replace(/\/+$/, '') === dest) return true;
363:   }
364:   for (const [root, files] of Object.entries(state.sourceFiles)) {
365:     const r = root.replace(/\/+$/, '').replace(/\/+/g, '/');
366:     if (dest === r) return true;
367:     if (!dest.startsWith(`${r}/`)) continue;
368:     const rel = dest.slice(r.length + 1);
369:     return Object.values(files).some(f => f.path.startsWith(`${rel}/`));
370:   }
371:   return false;
372: }
