39: /** Plan pur sur le state courant. Les choix de fichiers disparus de l'index
40:  *  épars sont ignorés silencieusement (index périmé). */
41: export function buildRangementPlan(): RangementPlan {
42:   const plan: RangementPlan = { groups: [], noYear: [], twinInDest: [], unknownStyle: [] };
43:   const tax = currentTaxonomy();
44:   const byDir = new Map<string, PlanGroup>();
45:   for (const [fullpath, choice] of state.styleChoices) {
46:     const found = findEparsEntry(state.eparsFiles, fullpath);
47:     if (!found) continue;
48:     const dest = tax ? destFor(tax, choice.style, yearOf(found.entry), choice.tranche) : null;
49:     if (!dest) {
50:       plan.unknownStyle.push(fullpath);
51:       continue;
52:     }
53:     if (dest.needsYear) {
54:       plan.noYear.push(fullpath);
55:       continue;
56:     }
57:     const twin = state.dupMatches.get(fullpath)?.sourceFullPath;
58:     if (twin?.startsWith(`${dest.dir}/`)) {
59:       plan.twinInDest.push(fullpath);
60:       continue;
61:     }
62:     let group = byDir.get(dest.dir);
63:     if (!group) {
64:       group = { dest, files: [] };
65:       byDir.set(dest.dir, group);
66:     }
67:     group.files.push({ filename: found.filename, eparDir: found.eparDir, fullpath });
68:   }
69:   plan.groups = [...byDir.values()].sort((a, b) => a.dest.name.localeCompare(b.dest.name));
70:   return plan;
71: }
