119: /** Enchaîne les copies dossier par dossier (séquentiel : copyFilesTo mute
120:  *  l'index et recharge le journal), retire des choix les fichiers copiés,
121:  *  laisse les échecs/exclus en session. Exporte les choix (style →
122:  *  /styles/review, EPIC-035 P3) pour apply_styles.py --review. Renvoie
123:  *  {copied, total}. */
124: export async function applyRangementPlan(plan: RangementPlan): Promise<{ copied: number; total: number }> {
125:   const done: string[] = [];
126:   const notes = new Set<string>();
127:   let total = 0;
128:   for (const g of plan.groups) {
129:     total += g.files.length;
130:     const r = await copyFilesTo(g.dest.dir, g.files);
131:     done.push(...r.copied);
132:     if (r.styleNote) notes.add(r.styleNote); // EPIC-043 : le tag suit le rangement
133:   }
134:   if (done.length) {
135:     await exportStyleChoices(done);
136:     const next = new Map(state.styleChoices);
137:     for (const fp of done) next.delete(fp);
138:     state.styleChoices = next;
139:     refreshStyleCells(done);
140:   }
141:   updateStyleRecap();
142:   showToast(
143:     `✓ ${done.length}/${total} copié${done.length > 1 ? 's' : ''} · ${plural(plan.groups.length, 'dossier')}${[...notes].join('')}`,
144:   );
145:   return { copied: done.length, total };
146: }
