148: /** POST /styles/review : persiste {fullpath: {style, tranche}} pour
149:  *  apply_styles.py --review (écriture TCON hors navigateur). Échec non
150:  *  bloquant : la copie a réussi, un simple message d'état suffit. */
151: async function exportStyleChoices(fullpaths: string[]): Promise<void> {
152:   const choices: Record<string, { style: string; tranche: number | null }> = {};
153:   for (const fp of fullpaths) {
154:     const c = state.styleChoices.get(fp);
155:     if (c) choices[fp] = { style: c.style, tranche: c.tranche };
156:   }
