162: /** Hotkeys déterministes : styles par volume décroissant (puis id), chacun
163:  *  prend la première lettre libre parmi : initiales de ses segments, puis
164:  *  lettres de son id, puis n'importe quelle lettre libre a-z. Épuisé → null. */
165: export function deriveHotkeys(tax: Taxonomy): Map<string, string | null> {
166:   const ordered = [...tax.styles.values()].sort(byCountThenId);
167:   const taken = new Set<string>();
168:   const out = new Map<string, string | null>();
169:   const alphabet = 'abcdefghijklmnopqrstuvwxyz';
170:   for (const def of ordered) {
171:     const candidates = [...def.id.split('_').map(seg => seg[0]), ...def.id.replace(/_/g, ''), ...alphabet];
172:     const key = candidates.find(c => !taken.has(c)) ?? null;
173:     if (key) taken.add(key);
174:     out.set(def.id, key);
175:   }
176:   return out;
177: }

